import { useState, type ChangeEvent, type FormEvent } from 'react';
import { JxButton } from '@jinx-ui/react';

// В README пакета задокументированы только JxButton (variant), оверлеи и модель
// value/onValueChange. Имена полевых компонентов там не названы, поэтому поля —
// нативные input'ы с jx-классами; сверьтесь с API библиотеки и замените при необходимости.

const STEPS = ['Контакты', 'Адрес', 'Проверка'] as const;

export interface RegistrationValues {
  email: string;
  phone: string;
  city: string;
  street: string;
}

export interface RegistrationFormProps {
  onSubmit: (values: RegistrationValues) => void;
}

export default function RegistrationForm({ onSubmit }: RegistrationFormProps) {
  const [step, setStep] = useState(0);
  const [values, setValues] = useState<RegistrationValues>({
    email: '',
    phone: '',
    city: '',
    street: '',
  });

  const isLast = step === STEPS.length - 1;

  const bind = (key: keyof RegistrationValues) => ({
    id: `registration-${key}`,
    className: 'jx-input',
    value: values[key],
    onChange: (event: ChangeEvent<HTMLInputElement>) =>
      setValues((prev) => ({ ...prev, [key]: event.target.value })),
  });

  const handleSubmit = (event: FormEvent<HTMLFormElement>) => {
    event.preventDefault();
    if (isLast) {
      onSubmit(values);
      return;
    }
    setStep((current) => current + 1);
  };

  return (
    <form
      className="jx-stack"
      onSubmit={handleSubmit}
      style={{ display: 'grid', gap: 'var(--jx-space-5)' }}
    >
      <ol
        aria-label="Шаги регистрации"
        className="jx-stepper"
        style={{
          display: 'grid',
          gridAutoFlow: 'column',
          gap: 'var(--jx-space-3)',
          margin: 0,
          padding: 0,
          listStyle: 'none',
        }}
      >
        {STEPS.map((label, index) => (
          <li
            key={label}
            aria-current={index === step ? 'step' : undefined}
            style={{
              display: 'grid',
              gap: 'var(--jx-space-2)',
              color:
                index === step ? 'var(--jx-color-accent)' : 'var(--jx-color-fg-muted)',
            }}
          >
            <span
              aria-hidden="true"
              style={{
                height: 'var(--jx-space-1)',
                borderRadius: 'var(--jx-radius-full)',
                background:
                  index <= step ? 'var(--jx-color-accent)' : 'var(--jx-color-border)',
              }}
            />
            <span>
              {index + 1}. {label}
            </span>
          </li>
        ))}
      </ol>

      <fieldset
        style={{
          display: 'grid',
          gap: 'var(--jx-space-4)',
          border: 0,
          margin: 0,
          padding: 0,
        }}
      >
        <legend style={{ padding: 0 }}>{STEPS[step]}</legend>

        {step === 0 && (
          <>
            <label className="jx-field" htmlFor="registration-email">
              Email
              <input type="email" autoComplete="email" {...bind('email')} />
            </label>
            <label className="jx-field" htmlFor="registration-phone">
              Телефон
              <input type="tel" autoComplete="tel" {...bind('phone')} />
            </label>
          </>
        )}

        {step === 1 && (
          <>
            <label className="jx-field" htmlFor="registration-city">
              Город
              <input type="text" autoComplete="address-level2" {...bind('city')} />
            </label>
            <label className="jx-field" htmlFor="registration-street">
              Улица и дом
              <input type="text" autoComplete="street-address" {...bind('street')} />
            </label>
          </>
        )}

        {step === 2 && (
          <dl
            style={{
              display: 'grid',
              gridTemplateColumns: 'auto 1fr',
              gap: 'var(--jx-space-2) var(--jx-space-4)',
              margin: 0,
            }}
          >
            <dt style={{ color: 'var(--jx-color-fg-muted)' }}>Email</dt>
            <dd style={{ margin: 0 }}>{values.email || '—'}</dd>
            <dt style={{ color: 'var(--jx-color-fg-muted)' }}>Телефон</dt>
            <dd style={{ margin: 0 }}>{values.phone || '—'}</dd>
            <dt style={{ color: 'var(--jx-color-fg-muted)' }}>Город</dt>
            <dd style={{ margin: 0 }}>{values.city || '—'}</dd>
            <dt style={{ color: 'var(--jx-color-fg-muted)' }}>Улица и дом</dt>
            <dd style={{ margin: 0 }}>{values.street || '—'}</dd>
          </dl>
        )}
      </fieldset>

      <div style={{ display: 'flex', gap: 'var(--jx-space-3)' }}>
        <JxButton
          type="button"
          variant="secondary"
          disabled={step === 0}
          onClick={() => setStep((current) => Math.max(0, current - 1))}
        >
          Назад
        </JxButton>
        <JxButton type="submit" variant="primary">
          {isLast ? 'Отправить' : 'Дальше'}
        </JxButton>
      </div>
    </form>
  );
}

